const json=(value,status=200)=>new Response(JSON.stringify(value),{status,headers:{"content-type":"application/json; charset=utf-8"}});
const validPhone=value=>/^[0-9+().\s-]{8,20}$/.test(value);
export default {async fetch(request,env){const url=new URL(request.url);if(url.pathname==='/api/leads'){if(request.method!=='POST')return json({error:'Phương thức không được hỗ trợ'},405);try{const body=await request.json();const fullName=String(body.fullName||'').trim(),phone=String(body.phone||'').trim(),email=String(body.email||'').trim().toLowerCase(),interest=String(body.interest||'Chưa xác định').trim(),consent=body.consent==='on'||body.consent===true;if(fullName.length<2||fullName.length>120||!validPhone(phone)||!/^\S+@\S+\.\S+$/.test(email)||!consent)return json({error:'Vui lòng điền đúng thông tin và xác nhận đồng ý liên hệ.'},400);await env.DB.prepare('INSERT INTO leads (full_name, phone, email, interest, consented_at) VALUES (?, ?, ?, ?, CURRENT_TIMESTAMP)').bind(fullName,phone,email,interest).run();return json({ok:true},201)}catch(error){return json({error:'Không thể lưu đăng ký lúc này. Vui lòng thử lại.'},500)}}if(env.ASSETS)return env.ASSETS.fetch(request);return new Response('Không tìm thấy trang.',{status:404})}};
